import{_ as p,a0 as o,w as h,s as d,ao as l,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Bash 基础知识系列 #2：在 Bash 中使用变量 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基础知识系列 #2：在 Bash 中使用变量 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基础知识系列 #2：在 Bash 中使用变量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基础知识系列 #2：在 Bash 中使用变量 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230619.1 ⭐️⭐️ Bash Basics Series 2 Using Variables in Bash","title":"Bash 基础知识系列 #2：在 Bash 中使用变量","tag":"202307","desc":""},"relativePath":"202307/20230619.1 ⭐️⭐️ Bash Basics Series 2 Using Variables in Bash.md","filePath":"[post].md"}'),r={name:"202307/20230619.1 ⭐️⭐️ Bash Basics Series 2 Using Variables in Bash.md"};function g(b,s,c,k,u,m){const e=o("Link");return h(),d("div",null,[s[22]||(s[22]=l(`<h1 id="bash-基础知识系列-2-在-bash-中使用变量" tabindex="-1">Bash 基础知识系列 #2：在 Bash 中使用变量 <a class="header-anchor" href="#bash-基础知识系列-2-在-bash-中使用变量" aria-label="Permalink to “Bash 基础知识系列 #2：在 Bash 中使用变量”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/12/111750bzruv9jiako6j694.jpg" alt=""></p><blockquote><p>在本章的 Bash 基础知识系列中，学习在 Bash 脚本中使用变量。</p></blockquote><p>在 Bash 基础知识系列的第一部分中，我简要提到了变量。现在是时候在本章中详细了解它们了。</p><p>如果你曾经进行过任何类型的编码，你一定熟悉术语“变量”。</p><p>如果没有，请将变量视为保存信息的盒子，并且该信息可以随着时间的推移而改变。</p><p>让我们看看如何使用它们。</p><h3 id="在-bash-shell-中使用变量" tabindex="-1">在 Bash shell 中使用变量 <a class="header-anchor" href="#在-bash-shell-中使用变量" aria-label="Permalink to “在 Bash shell 中使用变量”">​</a></h3><p>打开终端并使用一个随机的数字 4 初始化变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var=4</span></span></code></pre></div><p>现在你有一个名为 <code>var</code> 的变量，它的值为 <code>4</code>。想验证一下吗？ <strong>通过在变量名前添加 <code>$</code> 来访问变量的值</strong>。这称为参数扩展。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[abhishek@itsfoss]:~$ echo The value of var is $var</span></span>
<span class="line"><span>The value of var is 4</span></span></code></pre></div><blockquote><p>🚧 变量初始化时 <code>=</code> 前后不能有空格。</p></blockquote><p>如果需要，你可以将该值更改为其他值：</p><p><img src="https://itsfoss.com/content/images/2023/06/Using-variables-in-shell.png" alt="Using variables in shell"></p><p>在 Bash shell 中，变量可以是数字、字符或字符串（包括空格在内的字符）。</p><p><img src="https://itsfoss.com/content/images/2023/06/bash-variables-types.png" alt="Different variable types in Bash shell"></p><blockquote><p>💡 与 Linux 中的其他事物一样，变量名称也区分大小写。它们可以由字母、数字和下划线 “<code>_</code>” 组成。</p></blockquote><h3 id="在-bash-脚本中使用变量" tabindex="-1">在 Bash 脚本中使用变量 <a class="header-anchor" href="#在-bash-脚本中使用变量" aria-label="Permalink to “在 Bash 脚本中使用变量”">​</a></h3><p>你是否注意到我没有运行 shell 脚本来显示变量示例？ 你可以直接在 shell 中做很多事情.当你关闭终端时，你创建的那些变量将不再存在。</p><p>但是，你的发行版通常会添加全局变量，以便可以在所有脚本和 shell 中访问它们。</p><p>让我们再写一些脚本.你应该之前创建了脚本目录，但无论哪种情况，此命令都会处理该目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p bash_scripts &amp;&amp; cd bash_scripts</span></span></code></pre></div><p>基本上，如果 <code>bash_scripts</code> 目录尚不存在，它将创建它，然后切换到该目录。</p><p>这里让我们使用以下文本创建一个名为 <code>knock.sh</code> 的新脚本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo knock, knock</span></span>
<span class="line"><span>echo &quot;Who&#39;s there?&quot;</span></span>
<span class="line"><span>echo &quot;It&#39;s me, $USER&quot;</span></span></code></pre></div><p>更改文件权限并运行脚本。你在上一章中已经学到了。</p><p>这是它为我生成的内容：</p><p><img src="https://itsfoss.com/content/images/2023/06/using-global-variable-bash-script.png" alt="Using global variable in Bahs script"></p><p><strong>你是否注意到它如何自动将我的名字添加到其中？</strong> 这就是包含用户名的全局变量 <code>$USER</code> 的魔力。</p>`,30)),n("p",null,[s[1]||(s[1]=a("你可能还注意到，我有时将 ",-1)),s[2]||(s[2]=n("code",null,'"',-1)),s[3]||(s[3]=a(" 与 ",-1)),s[4]||(s[4]=n("code",null,"echo",-1)),s[5]||(s[5]=a(" 一起使用，但其他时候则不使用。这是故意的。",-1)),i(e,{href:"https://linuxhandbook.com:443/quotes-in-bash/"},{default:t(()=>[...s[0]||(s[0]=[a("bash 中的引号",-1)])]),_:1}),s[6]||(s[6]=a(" 有特殊含义。它们可用于处理空格和其他特殊字符。让我展示一个例子。",-1))]),s[23]||(s[23]=l(`<h3 id="处理变量中的空格" tabindex="-1">处理变量中的空格 <a class="header-anchor" href="#处理变量中的空格" aria-label="Permalink to “处理变量中的空格”">​</a></h3><p>假设你必须使用一个名为 <code>greetings</code> 的变量，其值为 <code>hello and welcome</code>。</p><p>如果你尝试像这样初始化变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>greetings=Hello and Welcome</span></span></code></pre></div><p>你会得到这样的错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Command &#39;and&#39; not found, but can be installed with:</span></span>
<span class="line"><span>sudo apt install and</span></span></code></pre></div><p>这就是为什么你需要使用单引号或双引号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>greetings=&quot;Hello and Welcome&quot;</span></span></code></pre></div><p>现在你可以根据需要使用该变量。</p><p><img src="https://itsfoss.com/content/images/2023/06/using-spaces-in-bash-variable.png" alt="Using spaces in variable names in bash"></p><h3 id="将命令输出分配给变量" tabindex="-1">将命令输出分配给变量 <a class="header-anchor" href="#将命令输出分配给变量" aria-label="Permalink to “将命令输出分配给变量”">​</a></h3><p>是的！你可以将命令的输出存储在变量中并在脚本中使用它们。这称为命令替换。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var=$(command)</span></span></code></pre></div><p>这是一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[abhishek@itsfoss]:~$ today=$(date +%D)</span></span>
<span class="line"><span>[abhishek@itsfoss]:~$ echo &quot;Today&#39;s date is $today&quot;</span></span>
<span class="line"><span>Today&#39;s date is 06/19/23</span></span>
<span class="line"><span>[abhishek@itsfoss]:~$</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/command-substitue-bash-variable.png" alt="Command substitution in bash"></p><p>旧语法使用反引号而不是 <code>$()</code> 进行命令替换。虽然它可能仍然有效，但你应该使用新的推荐符号。</p><blockquote><p>💡 变量会更改值，除非你声明一个“常量”变量，如下所示：<code>readonly pi=3.14</code>。在这种情况下，变量 <code>pi</code> 的值无法更改，因为它被声明为 <code>readlonly</code>。</p></blockquote><h3 id="🏋️-练习时间" tabindex="-1">🏋️ 练习时间 <a class="header-anchor" href="#🏋️-练习时间" aria-label="Permalink to “🏋️ 练习时间”">​</a></h3><p>是时候练习你所学到的东西了。这里有一些练习来测试你的学习情况。</p><p><strong>练习 1</strong>：编写一个 bash 脚本，以以下格式打印你的用户名、当前工作目录、主目录和默认 shell。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hello, there</span></span>
<span class="line"><span>My name is XYZ</span></span>
<span class="line"><span>My current location is XYZ</span></span>
<span class="line"><span>My home directory is XYZ</span></span>
<span class="line"><span>My default shell is XYZ</span></span></code></pre></div><p><strong>提示</strong>：使用全局变量 <code>$USER</code>、<code>$PWD</code>、<code>$HOME</code> 和 <code>$SHELL</code>。</p><p><strong>练习 2：</strong> 编写一个 bash 脚本，声明一个名为 <code>price</code> 的变量.使用它来获取以下格式的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Today&#39;s price is $X</span></span>
<span class="line"><span>Tomorrow&#39;s price is $Y</span></span></code></pre></div><p>其中 X 是变量 <code>price</code> 的初始值，并且明天价格翻倍。</p><p><strong>提示</strong>：使用 <code>\\</code> 转义特殊字符 <code>$</code>。</p><p>练习的答案可以在社区的这个专用帖子中讨论。</p><p>在 Bash 基础知识系列的下一章中，你将了解如何通过传递参数和接受用户输入来使 bash 脚本具有交互性。</p><p><em>（题图：MJ/37c5c26e-3289-4ebd-b8ae-88eb8a3b2eb1）</em></p><hr>`,31)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://itsfoss.com/bash-use-variables/"},{default:t(()=>[...s[7]||(s[7]=[a("https://itsfoss.com/bash-use-variables/",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...s[9]||(s[9]=[a("Abhishek Prakash",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[10]||(s[10]=[a("lkxed",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const C=p(r,[["render",g]]);export{v as __pageData,C as default};
